#!/bin/bash
set -euo pipefail
umask 077
[[ $EUID -eq 0 ]] || { echo '请用 sudo bash 执行'; exit 1; }
exec 9>/run/football-injury-bridge-install.lock
flock -n 9 || { echo '安装正在运行'; exit 1; }
test -s /etc/football-web/access.json
test -s /etc/football-github-sync/token
test -s /opt/football-web/injury_view.py
test -s /opt/football-github-sync/sync.py
if ! /usr/bin/python3 -c 'from cryptography.hazmat.primitives.ciphers.aead import AESGCM' 2>/dev/null; then
 echo '正在安装系统加密库。'
 apt-get -o Acquire::Retries=1 -o Acquire::http::Timeout=30 -o Acquire::https::Timeout=30 update -qq
 DEBIAN_FRONTEND=noninteractive apt-get -y install python3-cryptography
fi
install -d -m 700 /opt/football-injury-bridge
systemctl stop football-injury-bridge.timer football-injury-bridge.service 2>/dev/null || true
python3 - <<'CODE'
import base64,os,py_compile,datetime
from pathlib import Path
root=Path('/opt/football-injury-bridge')
files={'injury_crypto.py': '', 'sync_injuries.py': '', 'read_encrypted_injuries.py': ''}
for name,value in files.items():
 p=root/name
 if p.exists():p.with_suffix('.backup-'+datetime.datetime.now().strftime('%Y%m%d%H%M%S')).write_bytes(p.read_bytes())
 t=p.with_suffix('.new');t.write_bytes(base64.b64decode(value));py_compile.compile(str(t),doraise=True);t.chmod(0o600);os.replace(t,p)
import sys,json
sys.path.insert(0,str(root))
from injury_crypto import encrypt,decrypt
c=json.loads(Path('/etc/football-web/access.json').read_text())
assert decrypt(encrypt({'test':True},c['api_key']),c['api_key'])=={'test':True}
print('INJURY_ENCRYPTION_CHECK_OK')
CODE
cat > /etc/systemd/system/football-injury-bridge.service <<'UNIT'
[Unit]
Description=Sync authenticated encrypted injury snapshot for private analysis
After=network-online.target football-web.service football-injury-view.service
[Service]
Type=oneshot
ExecStart=/usr/bin/python3 /opt/football-injury-bridge/sync_injuries.py
TimeoutStartSec=240
UMask=0077
NoNewPrivileges=true
ProtectSystem=strict
ProtectHome=true
PrivateTmp=true
ReadWritePaths=/run
UNIT
cat > /etc/systemd/system/football-injury-bridge.timer <<'UNIT'
[Unit]
Description=Sync encrypted injury snapshot every 30 minutes
[Timer]
OnBootSec=3min
OnUnitActiveSec=30min
[Install]
WantedBy=timers.target
UNIT
systemctl daemon-reload
systemctl enable --now football-injury-bridge.timer
# Refresh only the local view, without consuming an API-Football request.
systemctl start football-injury-view.service
echo 'INJURY_BRIDGE_INSTALLED：每30分钟同步加密伤停，不额外请求 API-Football。'
echo '现在执行首次同步；网络慢时可能需要几分钟。'
if systemctl start football-injury-bridge.service; then
 journalctl -u football-injury-bridge.service -n 8 --no-pager
else
 echo '首次同步失败，查看下方日志；定时任务已安装，不要重复安装。'
 journalctl -u football-injury-bridge.service -n 10 --no-pager
 exit 1
fi
echo '请把最后的 INJURY_BRIDGE_SYNC_OK 结果告诉我，我会读取密文并验证解密。'
